import { baseApi } from "./baseApi";

export type LobbyGame = {
  id: string;
  title: string;
  subtitle: string;
  imageUrl: string | null;
  category: "slots" | "live" | "jackpot" | "popular";
  isNew: boolean;
  isLive: boolean;
};

type GamesListResponse = {
  cached?: boolean;
  data?: unknown;
};

function asRecord(v: unknown): Record<string, unknown> | null {
  return v && typeof v === "object" ? (v as Record<string, unknown>) : null;
}

function pickString(obj: Record<string, unknown>, keys: string[]): string {
  for (const k of keys) {
    const v = obj[k];
    if (typeof v === "string" && v.trim()) return v.trim();
    if (typeof v === "number") return String(v);
  }
  return "";
}

function detectCategory(raw: Record<string, unknown>): LobbyGame["category"] {
  const blob = [
    pickString(raw, ["category", "categories", "type", "game_category"]),
    pickString(raw, ["name", "game_name", "title"]),
  ]
    .join(" ")
    .toLowerCase();
  if (blob.includes("live") || blob.includes("roulette") || blob.includes("baccarat")) {
    return "live";
  }
  if (blob.includes("jackpot")) return "jackpot";
  if (blob.includes("popular") || blob.includes("hot")) return "popular";
  return "slots";
}

export function normalizeGamesPayload(payload: unknown): LobbyGame[] {
  const root = asRecord(payload);
  const data = asRecord(root?.data) ?? root;
  const listCandidate =
    data?.games ??
    data?.Items ??
    data?.items ??
    data?.list ??
    (Array.isArray(data) ? data : null);

  if (!Array.isArray(listCandidate)) return [];

  return listCandidate
    .map((item, index) => {
      const row = asRecord(item);
      if (!row) return null;
      const id =
        pickString(row, [
          "extearnal_game_id",
          "external_game_id",
          "game_id",
          "id",
          "gameId",
        ]) || `game-${index}`;
      const title =
        pickString(row, ["name", "game_name", "title", "gameName"]) ||
        `Game ${index + 1}`;
      const subtitle =
        pickString(row, [
          "provider_title",
          "provider",
          "category",
          "categories",
          "type",
        ]) || "Casino";
      const imageUrl =
        pickString(row, [
          "icon_2",
          "icon",
          "icon_url",
          "image",
          "image_url",
          "thumbnail",
          "img",
        ]) || null;
      const category = detectCategory(row);
      const isLive = category === "live";
      const isNew = index < 8;

      return {
        id,
        title,
        subtitle,
        imageUrl,
        category,
        isNew,
        isLive,
      } satisfies LobbyGame;
    })
    .filter(Boolean) as LobbyGame[];
}

