"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { AuthGuard } from "@/components/auth/AuthGuard";
import { LobbyHeader } from "@/components/lobby/LobbyHeader";
import {
  CategorySearchBar,
  type LobbyCategory,
} from "@/components/lobby/CategorySearchBar";
import { GameGrid } from "@/components/lobby/GameGrid";
import { useAppDispatch } from "@/store/hooks";
import { clearCredentials } from "@/store/features/auth/authSlice";
import { clearAuthSession } from "@/lib/auth-storage";
import { useLogoutMutation, useMeQuery } from "@/store/api/authApi";
import { useGetGamesQuery, type LobbyGame } from "@/store/api/gamesApi";
import { useGetRateQuery } from "@/store/api/paymentsApi";

export default function GamesPage() {
  return (
    <AuthGuard>
      <LobbyPage />
    </AuthGuard>
  );
}

function LobbyPage() {
  const router = useRouter();
  const dispatch = useAppDispatch();
  const [category, setCategory] = useState<LobbyCategory>("slots");
  const [search, setSearch] = useState("");

  const { data: me } = useMeQuery();
  const { data: rateData } = useGetRateQuery();
  const { data: gamesData, isFetching } = useGetGamesQuery({
    limit: 48,
    offset: 0,
    search: search.trim() || undefined,
  });
  const [logoutApi] = useLogoutMutation();

  const filtered = useMemo(() => {
    const list = gamesData?.games ?? [];
    const q = search.trim().toLowerCase();
    return list.filter((g) => {
      const matchSearch =
        !q ||
        g.title.toLowerCase().includes(q) ||
        g.subtitle.toLowerCase().includes(q);

      if (gamesData?.fromFallback) {
        return g.category === category && matchSearch;
      }

      // Live CMS: soft category match; "slots" shows full list
      if (category === "slots") return matchSearch;
      const hay = `${g.category} ${g.title} ${g.subtitle}`.toLowerCase();
      return hay.includes(category) && matchSearch;
    });
  }, [gamesData, category, search]);

  async function onLogout() {
    try {
      await logoutApi().unwrap();
    } catch {
      // ignore
    }
    clearAuthSession();
    dispatch(clearCredentials());
    router.replace("/login");
  }

  function onPlay(game: LobbyGame) {
    // Launch wiring next — for now stay on lobby
    console.info("play", game.id, game.title);
  }

  return (
    <div className="min-h-screen bg-[#050805] text-[#f5efe0]">
      <LobbyHeader
        active="games"
        balanceUsd={me?.balance?.realBalance ?? "0"}
        mmkPerUsd={rateData?.mmkPerUsd ?? "4500"}
        onLogout={onLogout}
      />

      <main className="mx-auto max-w-[1440px] px-4 py-5 md:px-8 md:py-6">
        <CategorySearchBar
          category={category}
          search={search}
          onCategoryChange={setCategory}
          onSearchChange={setSearch}
        />

        {gamesData?.fromFallback ? (
          <p className="mt-3 text-xs text-[#8a8a8a]">
            Showing demo catalog (CMS returned no games for this partner yet).
          </p>
        ) : null}

        <div className="mt-5">
          <GameGrid games={filtered} loading={isFetching && !gamesData} onPlay={onPlay} />
        </div>
      </main>
    </div>
  );
}
