"use client";

import type { LobbyGame } from "@/store/api/gamesApi";

const GRADIENTS = [
  "from-[#3a1c71] via-[#d76d77] to-[#ffaf7b]",
  "from-[#0f2027] via-[#203a43] to-[#2c5364]",
  "from-[#1a2a6c] via-[#b21f1f] to-[#fdbb2d]",
  "from-[#134e5e] via-[#71b280] to-[#134e5e]",
  "from-[#4a00e0] via-[#8e2de2] to-[#4a00e0]",
  "from-[#232526] via-[#414345] to-[#232526]",
  "from-[#c31432] via-[#240b36] to-[#c31432]",
  "from-[#141e30] via-[#243b55] to-[#141e30]",
];

type Props = {
  game: LobbyGame;
  index: number;
  onPlay?: (game: LobbyGame) => void;
};

export function GameCard({ game, index, onPlay }: Props) {
  const gradient = GRADIENTS[index % GRADIENTS.length];

  return (
    <button
      type="button"
      onClick={() => onPlay?.(game)}
      className="group relative aspect-[3/4] w-full overflow-hidden rounded-xl border border-[#d4af37]/45 bg-[#0a0f0c] text-left shadow-[0_8px_24px_rgba(0,0,0,0.45)] transition hover:-translate-y-0.5 hover:border-[#e8c547] hover:shadow-[0_12px_30px_rgba(212,175,55,0.18)]"
    >
      {game.imageUrl ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={game.imageUrl}
          alt={game.title}
          className="absolute inset-0 h-full w-full object-cover transition duration-500 group-hover:scale-105"
        />
      ) : (
        <div
          className={`absolute inset-0 bg-gradient-to-br ${gradient} opacity-90`}
          aria-hidden
        />
      )}

      <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent" />

      {game.isNew ? (
        <span className="absolute left-2 top-2 rounded bg-[#1f9d55] px-1.5 py-0.5 text-[0.58rem] font-bold tracking-wide text-white">
          NEW
        </span>
      ) : null}
      {game.isLive ? (
        <span className="absolute right-2 top-2 rounded bg-[#e11d48] px-1.5 py-0.5 text-[0.58rem] font-bold tracking-wide text-white">
          LIVE
        </span>
      ) : null}

      <div className="absolute inset-x-0 bottom-0 p-2.5 sm:p-3">
        <p className="truncate text-sm font-bold text-white sm:text-[0.95rem]">
          {game.title}
        </p>
        <p className="mt-0.5 truncate text-[0.7rem] font-medium text-[#d4af37]">
          {game.subtitle}
        </p>
      </div>
    </button>
  );
}
