"use client";

import type { LobbyGame } from "@/store/api/gamesApi";
import { GameCard } from "./GameCard";

type Props = {
  games: LobbyGame[];
  loading?: boolean;
  onPlay?: (game: LobbyGame) => void;
};

export function GameGrid({ games, loading, onPlay }: Props) {
  if (loading) {
    return (
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 md:gap-4">
        {Array.from({ length: 12 }).map((_, i) => (
          <div
            key={i}
            className="aspect-[3/4] animate-pulse rounded-xl border border-[#d4af37]/20 bg-[#121512]"
          />
        ))}
      </div>
    );
  }

  if (games.length === 0) {
    return (
      <div className="rounded-xl border border-[#d4af37]/30 bg-black/40 px-6 py-16 text-center text-[#c5bba3]">
        No games found.
      </div>
    );
  }

  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 md:gap-4">
      {games.map((game, index) => (
        <GameCard key={game.id} game={game} index={index} onPlay={onPlay} />
      ))}
    </div>
  );
}
