"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { formatMmk, formatUsd } from "@/lib/money-format";

type NavKey = "home" | "games" | "wallet" | "deposit";

type LobbyHeaderProps = {
  active?: NavKey;
  balanceUsd?: string;
  mmkPerUsd?: string;
  onLogout?: () => void;
};

const NAV: { key: NavKey; label: string; href: string }[] = [
  { key: "home", label: "Home", href: "/games" },
  { key: "games", label: "Games", href: "/games" },
  { key: "wallet", label: "Wallet", href: "/games" },
  { key: "deposit", label: "Deposit", href: "/games" },
];

export function LobbyHeader({
  active = "games",
  balanceUsd = "0",
  mmkPerUsd = "4500",
  onLogout,
}: LobbyHeaderProps) {
  const [hidden, setHidden] = useState(false);
  const usd = formatUsd(balanceUsd);
  const mmk = formatMmk(balanceUsd, mmkPerUsd);

  return (
    <header className="border-b border-white/5 bg-[#050805]">
      <div className="mx-auto flex h-[78px] max-w-[1440px] items-center justify-between gap-4 px-4 md:px-8">
        <Link href="/games" className="flex shrink-0 items-center gap-3">
          <Image
            src="/brand/lotus-mark.jpg"
            alt="Shwe Dunn"
            width={42}
            height={42}
            className="rounded-full object-cover ring-1 ring-[#d4af37]/50"
            priority
          />
          <div className="leading-tight">
            <p className="font-[family-name:var(--font-cinzel)] text-[1.05rem] font-semibold tracking-[0.14em] text-[#e8c547]">
              SHWE DUNN
            </p>
            <p className="text-[0.58rem] font-medium tracking-[0.18em] text-[#c5bba3]">
              PLAY RICH • WIN GOLD
            </p>
          </div>
        </Link>

        <nav className="hidden items-center gap-2 md:flex lg:gap-3">
          {NAV.map((item) => {
            const isActive = item.key === active;
            return (
              <Link
                key={item.key}
                href={item.href}
                className={`inline-flex items-center gap-2 rounded-full px-4 py-2 text-sm font-semibold transition ${
                  isActive
                    ? "bg-[#d4af37] text-[#1a1205] shadow-[0_0_20px_rgba(212,175,55,0.35)]"
                    : "text-[#f5efe0]/90 hover:text-[#e8c547]"
                }`}
              >
                <NavIcon name={item.key} active={isActive} />
                {item.label}
              </Link>
            );
          })}
        </nav>

        <div className="flex items-center gap-2 sm:gap-3">
          <div className="flex items-center gap-2 rounded-xl border border-white/20 bg-black/40 px-3 py-2 sm:gap-3 sm:px-4">
            <div className="text-right leading-tight">
              <p className="text-[0.58rem] font-semibold tracking-[0.14em] text-[#c5bba3]">
                BALANCE
              </p>
              <p className="text-sm font-bold text-white sm:text-[0.95rem]">
                {hidden ? "••••" : `${usd} USD`}
              </p>
            </div>
            <span className="px-1 text-lg font-light text-[#d4af37]">=</span>
            <div className="text-left leading-tight">
              <p className="text-[0.58rem] font-semibold tracking-[0.14em] text-[#c5bba3]">
                MMK
              </p>
              <p className="text-sm font-bold text-[#e8c547] sm:text-[0.95rem]">
                {hidden ? "••••" : mmk}
              </p>
            </div>
            <button
              type="button"
              aria-label={hidden ? "Show balance" : "Hide balance"}
              onClick={() => setHidden((v) => !v)}
              className="ml-1 text-[#d4af37] hover:text-[#f0d78c]"
            >
              <EyeIcon open={!hidden} />
            </button>
          </div>

          {onLogout ? (
            <button
              type="button"
              onClick={onLogout}
              className="hidden rounded-full border border-[#d4af37]/45 px-3 py-2 text-xs font-semibold tracking-wide text-[#e8c547] hover:bg-[#d4af37]/10 sm:inline-flex"
            >
              Log out
            </button>
          ) : null}
        </div>
      </div>
    </header>
  );
}

function NavIcon({ name, active }: { name: NavKey; active: boolean }) {
  const stroke = active ? "#1a1205" : "#d4af37";
  const common = {
    width: 16,
    height: 16,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke,
    strokeWidth: 1.8,
  } as const;

  if (name === "home") {
    return (
      <svg {...common} aria-hidden>
        <path d="M4 10.5 12 4l8 6.5V20a1 1 0 0 1-1 1h-5v-6H10v6H5a1 1 0 0 1-1-1v-9.5Z" />
      </svg>
    );
  }
  if (name === "games") {
    return (
      <svg {...common} aria-hidden>
        <path d="m12 3 8 4.5v9L12 21l-8-4.5v-9L12 3Z" />
        <path d="M12 12 20 7.5M12 12v9M12 12 4 7.5" />
      </svg>
    );
  }
  if (name === "wallet") {
    return (
      <svg {...common} aria-hidden>
        <rect x="3" y="6" width="18" height="13" rx="2" />
        <path d="M3 10h18M16 14.5h2" />
      </svg>
    );
  }
  return (
    <svg {...common} aria-hidden>
      <rect x="3" y="6" width="18" height="13" rx="2" />
      <path d="M7 6V5a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v1M12 11v5M9.5 13.5 12 11l2.5 2.5" />
    </svg>
  );
}

function EyeIcon({ open }: { open: boolean }) {
  if (open) {
    return (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" aria-hidden>
        <path d="M3 12s3.5-6 9-6 9 6 9 6-3.5 6-9 6-9-6-9-6Z" />
        <circle cx="12" cy="12" r="2.5" />
      </svg>
    );
  }
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" aria-hidden>
      <path d="M3 12s3.5-6 9-6 9 6 9 6-3.5 6-9 6-9-6-9-6Z" />
      <path d="m4 4 16 16" />
    </svg>
  );
}
